async function googleTranslate(t,f,to){if(!t)return t;if(f===to&&f!=="auto")return t;try{const u=`https://translate.googleapis.com/translate_a/single?client=gtx&sl=${f}&tl=${to}&dt=t&q=${encodeURIComponent(t)}`;const r=await fetch(u);const j=await r.json();let o="";j[0].forEach(x=>{if(x[0])o+=x[0];});return o||t;}catch{return t;}}
function getNodes(r){const w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentElement;if(!p)return NodeFilter.FILTER_REJECT;if(["SCRIPT","STYLE"].includes(p.tagName))return NodeFilter.FILTER_REJECT;if(p.closest("#langList, #chatMessages"))return NodeFilter.FILTER_REJECT;return n.nodeValue.trim().length>1?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;}});const a=[];let x;while(x=w.nextNode())a.push(x);return a;}
async function translateApp(l){if(!l||l==="en")return;const n=getNodes(document.body);const need=new Map();n.forEach(tn=>{const p=tn.parentElement;if(!p.dataset.o)p.dataset.o=tn.nodeValue;const o=p.dataset.o;const k=l+"::"+o.trim();if(transCache[k]){let t=transCache[k];if(BAD_FIX[t])t=BAD_FIX[t];tn.nodeValue=t;}else{if(!need.has(o))need.set(o,[]);need.get(o).push(tn);}});$$("input[placeholder], textarea[placeholder]").forEach(el=>{if(el.closest("#chatInputBar"))return;if(!el.dataset.oPh)el.dataset.oPh=el.placeholder;const o=el.dataset.oPh;const k=l+"::"+o.trim();if(transCache[k])el.placeholder=transCache[k];else if(o.trim()){if(!need.has(o))need.set(o,[]);}});if(need.size){for(const o of [...need.keys()]){let q=o.trim();if(q==="QR Code"&&FORCE_FIX["QR Code"][l]){const t=FORCE_FIX["QR Code"][l];transCache[l+"::"+o.trim()]=t;transCache[l+"::"+o]=t;(need.get(o)||[]).forEach(n=>{if(n.nodeType===3)n.nodeValue=t;});$$("input[placeholder], textarea[placeholder]").forEach(el=>{if(el.dataset.oPh===o)el.placeholder=t;});continue;}let isAt=q.toLowerCase()==="@username";if(isAt)q="username";let t=await googleTranslate(q,"en",l);if(isAt)t="@"+t;if(BAD_FIX[t])t=BAD_FIX[t];transCache[l+"::"+o.trim()]=t;transCache[l+"::"+o]=t;(need.get(o)||[]).forEach(n=>{if(n.nodeType===3)n.nodeValue=t;});$$("input[placeholder], textarea[placeholder]").forEach(el=>{if(el.dataset.oPh===o)el.placeholder=t;});}localStorage.setItem("ddchat_trans_v3",JSON.stringify(transCache));}}
async function setPresenceText(el,enText){if(!el)return;el.textContent=enText;const lang=localStorage.getItem("ddchat_lang")||"en";if(lang==="en")return;const key=lang+"::"+enText.trim();if(transCache[key]){el.textContent=transCache[key];}else{try{const t=await googleTranslate(enText,"en",lang);transCache[key]=t;localStorage.setItem("ddchat_trans_v3",JSON.stringify(transCache));el.textContent=t;}catch{}}}
