function startPresence(){if(!currentUser)return;const goOnline=()=>supabase.from("users").update({is_online:true,last_seen:new Date().toISOString(),current_chat_with:currentChatWith||null}).eq("id",currentUser.id).then(()=>{});const goOffline=()=>supabase.from("users").update({is_online:false,last_seen:new Date().toISOString(),current_chat_with:null}).eq("id",currentUser.id).then(()=>{});goOnline();if(heartbeatInterval)clearInterval(heartbeatInterval);heartbeatInterval=setInterval(goOnline,10000);window.addEventListener('beforeunload',goOffline);document.addEventListener('visibilitychange',()=>{if(document.hidden)goOffline();else goOnline();});}
function listenToOtherPresence(o){if(presenceChannel)supabase.removeChannel(presenceChannel);presenceChannel=supabase.channel('presence-'+o).on('postgres_changes',{event:'*',schema:'public',table:'users',filter:`id=eq.${o}`},p=>{const u=p.new;if(!u)return;userCache[o]={...userCache[o],...u,photoURL:u.photo_url,avatar:u.avatar,name:u.name,about:u.about,isOnline:u.is_online,lastSeen:u.last_seen?{toDate:()=>new Date(u.last_seen)}:null,currentChatWith:u.current_chat_with};const e=$("#chatLastSeen"),d=$("#chatAvatarStatus"),a=$("#chatAboutStatus");if(!e||!d)return;const i=u.is_online===true,c=u.current_chat_with===currentUser.id;d.style.display="block";if(a&&u.about)a.textContent=u.about;if(c&&i){setPresenceText(e,"Online");d.className="online";markMyMessagesAsRead();}else if(i){setPresenceText(e,"Online");d.className="online";}else{const l=u.last_seen?new Date(u.last_seen):new Date();const t=l.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:true});setPresenceText(e,`last seen today at ${t}`);d.className="offline";}}).subscribe();}
async function markMyMessagesAsRead(){if(!currentChatId)return;try{const {data}=await supabase.from("messages").select("id").eq("chat_id",currentChatId).eq("from_id",currentUser.id).neq("status","read");if(data)for(const m of data)await supabase.from("messages").update({status:"read",read:true}).eq("id",m.id);}catch{}}
supabase.auth.onAuthStateChange(async(e,s)=>{authChecked=true;const u=s?.user||null;if(u){currentUser={uid:u.id,id:u.id,email:u.email};const {data:d}=await supabase.from("users").select("*").eq("id",u.id).single();if(d){userCache[u.id]=d;let l=d.lang||localStorage.getItem("ddchat_lang")||"en";selectedLang=l;localStorage.setItem("ddchat_lang",l);if(l!=="en")setTimeout(()=>translateApp(l),400);if(!d.lang)try{await supabase.from("users").update({lang:l}).eq("id",u.id);}catch{} $("#profileName").textContent=d.name;$("#profileUsername").textContent="@"+d.username;const av=$("#profileAvatar");if(d.photo_url){av.innerHTML=`<img src="${d.photo_url}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;av.dataset.full=d.photo_url;}else{av.textContent=d.avatar||d.name[0].toUpperCase();av.dataset.full="";}const st=document.getElementById("profileStickyName");if(st)st.textContent=d.name;if(!d.dd_id){const ddId=Math.floor(10000000+Math.random()*90000000).toString();await supabase.from("users").update({dd_id:ddId}).eq("id",u.id);}}showScreen("app");startPresence();loadChats();loadGroups();loadStatus();loadCalls();}else{currentUser=null;if(heartbeatInterval)clearInterval(heartbeatInterval);if(presenceChannel)supabase.removeChannel(presenceChannel);if(chatChannel)supabase.removeChannel(chatChannel);if(chatsChannel)supabase.removeChannel(chatsChannel);if(localStorage.getItem("ddchat_lang"))showScreen("auth-screen");else showScreen("language-screen");}});
