function openFullPhoto(u){if(!u)return;showModal("Photo",`<div style="position:fixed;inset:0;background:#000;z-index:99999;display:flex;flex-direction:column"><div style="padding:15px;display:flex;align-items:center;background:#111"><button id="photoBackBtn" style="background:#333;border:none;width:42px;height:42px;border-radius:50%;color:white;font-size:22px;display:flex;align-items:center;justify-content:center;cursor:pointer">←</button><span style="color:white;margin-left:15px;font-weight:bold">Profile Photo</span></div><div style="flex:1;display:flex;align-items:center;justify-content:center;background:black;padding:10px"><img src="${u}" style="max-width:100%;max-height:85vh;object-fit:contain;border-radius:8px"/></div></div>`);setTimeout(()=>{const b=document.getElementById("photoBackBtn");if(b)b.onclick=()=>$("#modal").classList.add("hidden");},50);}
async function loadChats(){if(!currentUser)return;const {data:c,error:e}=await supabase.from("chats").select("*").contains("members",[currentUser.id]).order("updated_at",{ascending:false});const l=$("#chatList");if(e||!c||c.length===0){l.innerHTML="<li style='padding:15px;color:#8696a0'>No chats yet. Search username or DD ID above to start.</li>";return;}const m=new Map();c.forEach(x=>{const o=x.members.find(m=>m!==currentUser.id);if(!o)return;const ex=m.get(o);if(!ex)m.set(o,x);else if(new Date(x.updated_at)>new Date(ex.updated_at))m.set(o,x);});l.innerHTML="";for(const [o,d]of m){const un=d.unread_count?.[currentUser.id]||0;let ca=userCache[o];if(!ca){const {data:u}=await supabase.from("users").select("*").eq("id",o).single();if(u){userCache[o]=u;ca=u;}}const n=ca?.name||"DD User",le=ca?.avatar||n[0]||"U",ph=ca?.photo_url||ca?.photoURL||"";const av=ph?`<div style="width:48px;height:48px;border-radius:50%;overflow:hidden;flex-shrink:0"><img src="${ph}" style="width:100%;height:100%;object-fit:cover" loading="lazy"></div>`:`<div class="avatar" style="width:48px;height:48px;flex-shrink:0">${le}</div>`;const li=document.createElement("li");li.id="chat_"+o;li.style.display="flex";li.style.alignItems="center";li.style.gap="12px";li.style.padding="12px";li.style.borderBottom="1px solid rgba(255,255,255,0.06)";li.style.cursor="pointer";li.innerHTML=`${av}<div style="flex:1;min-width:0"><b style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(n)}</b><small style="color:#8696a0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block">${escapeHtml(d.last_msg||"Start chatting")}</small></div>${un>0?`<span class="unread-badge">${un}</span>`:''}`;li.onclick=()=>openChat(d.id,o,ca?.name||"");l.appendChild(li);}if(chatsChannel)supabase.removeChannel(chatsChannel);chatsChannel=supabase.channel('chats-list').on('postgres_changes',{event:'*',schema:'public',table:'chats'},()=>loadChats()).subscribe();}
$("#chatSearch").oninput=async e=>{const r=e.target.value.trim();if(r.length<1){loadChats();return;}const l=$("#chatList");l.innerHTML="<li style='padding:15px'>Searching...</li>";let f=[];const lo=r.toLowerCase();try{const {data}=await supabase.from("users").select("*").eq("username",lo);if(data)data.forEach(u=>{if(u.id!==currentUser.id)f.push(u);});}catch{}try{const {data}=await supabase.from("users").select("*").eq("dd_id",r);if(data)data.forEach(u=>{if(u.id!==currentUser.id&&!f.find(x=>x.id===u.id))f.push(u);});}catch{}const cl=r.replace("DD-","").replace("DD","").trim();if(cl!==r){try{const {data}=await supabase.from("users").select("*").eq("dd_id",cl);if(data)data.forEach(u=>{if(u.id!==currentUser.id&&!f.find(x=>x.id===u.id))f.push(u);});}catch{}}l.innerHTML="";if(f.length===0){l.innerHTML=`<li style='padding:15px'>No user found for "${escapeHtml(r)}"</li>`;return;}f.forEach(u=>{userCache[u.id]=u;const li=document.createElement("li");li.innerHTML=`<div class="avatar">${u.avatar||u.name[0]}</div><div><b>${escapeHtml(u.name)}</b><br><small>@${escapeHtml(u.username)} - DD ID: ${u.dd_id}</small></div>`;li.onclick=()=>startChat(u.id);l.appendChild(li);});};
async function startChat(o){const m=[currentUser.id,o].sort();const c=m.join("_");const {data}=await supabase.from("chats").select("id").eq("id",c).single();if(!data)await supabase.from("chats").insert({id:c,members:m,last_msg:"",unread_count:{[currentUser.id]:0,[o]:0},updated_at:new Date().toISOString()});openChat(c,o);}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","&quot;":"&#39;"}[c]));}
function formatTimeWithAMPM(d){if(!d)return"";return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:true});}
