function createFileViewerModal(){const d=document.createElement("div");d.id="fileViewerModal";d.style.cssText="position:fixed;inset:0;z-index:999999;display:none;align-items:center;justify-content:center;";d.innerHTML=`<div onclick="closeFileViewer()" style="position:absolute;inset:0;background:rgba(0,0,0,0.85)"></div><div style="position:relative;background:#121212;width:95%;max-width:600px;max-height:90vh;overflow-y:auto;border-radius:16px;z-index:2;display:flex;flex-direction:column"><div style="display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #222"><span id="viewerFileName" style="font-weight:bold;color:white">File</span><button onclick="closeFileViewer()" style="background:#222;border:none;color:white;width:36px;height:36px;border-radius:50%">✕</button></div><div id="viewerContent" style="padding:12px"></div><div style="display:flex;gap:10px;padding:12px"><button onclick="saveFileGlobal(currentViewerFile.url, currentViewerFile.name)" style="flex:1;padding:12px;border-radius:10px;border:none;background:#5E35B1;color:white;font-weight:bold">💾 Save to Phone</button><button onclick="translateFileText()" style="flex:1;padding:12px;border-radius:10px;border:none;background:#1e88e5;color:white;font-weight:bold">🌐 Translate</button></div><div id="viewerTranslation" style="padding:12px"></div></div>`;document.body.appendChild(d);}
window.translateFileText=async function(){const r=document.getElementById("viewerTranslation");r.innerHTML="🔍 Reading...";try{if(currentViewerFile.type==="image"){if(!window.Tesseract){await new Promise((a,b)=>{const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js";s.onload=a;s.onerror=b;document.head.appendChild(s);});}const {data:{text}}=await Tesseract.recognize(currentViewerFile.url,"eng");currentOcrText=text.trim();}else currentOcrText=currentViewerFile.name;if(!currentOcrText){r.innerHTML="No text";return;}const l=localStorage.getItem("ddchat_lang")||"en";const t=await googleTranslate(currentOcrText,"auto",l);r.innerHTML=`<div style="background:#1e1e1e;padding:12px;border-radius:10px;color:white;white-space:pre-wrap">${escapeHtml(t)}</div>`;}catch(e){r.innerHTML="Error: "+e.message;}};
function getFileBubbleHtml(d){const n=d.file_name||d.fileName||d.text?.replace("📎 ","")||"file";let u=d.file_url||d.fileUrl||d.audio_url||d.audioUrl||"";if(!u)return null;if(u.startsWith("blob:"))return `<div style="padding:8px;background:#3a1a1a;border-radius:8px;color:#ff8a8a;font-size:12px">⚠️ Voice expired - resend please</div>`;const s=escapeHtml(n);const i=d.file_type?.startsWith("image/")||d.msg_type==="image"||n.match(/\.(jpg|jpeg|png|gif|webp)$/i);const v=d.file_type?.startsWith("video/")||d.msg_type==="video";const o=d.file_type?.startsWith("audio/")||d.msg_type==="voice";if(i)return `<div><img src="${u}" loading="lazy" onclick="openFileViewer(this.src,'${s}','image')" style="max-width:220px;max-height:220px;border-radius:12px;display:block;object-fit:cover;cursor:pointer"></div>`;else if(v)return `<div><video src="${u}" controls preload="metadata" style="max-width:220px;border-radius:12px;display:block"></video><button onclick="openFileViewer('${u}','${s}','video')" style="font-size:12px;margin-top:6px;width:100%;background:#5E35B1;border:none;color:white;padding:10px;border-radius:8px;font-weight:bold">📺 View + Save</button></div>`;else if(o)return `<div style="min-width:200px;background:#2a1a6a;padding:8px;border-radius:12px"><audio controls preload="metadata" src="${u}" style="width:100%"></audio></div>`;else return `<div onclick="openFileViewer('${u}','${s}','doc')" style="display:flex;align-items:center;gap:10px;background:#2a1a6a;padding:12px;border-radius:12px;cursor:pointer;min-width:180px"><div style="font-size:28px">📄</div><div><div style="font-weight:bold;color:white;max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${s}</div><div style="font-size:11px;color:#aaa">Tap to open</div></div></div>`;}
function openChat(c,o,p=""){if(chatChannel)supabase.removeChannel(chatChannel);currentChatId=c;currentChatWith=o;showScreen("chat-view");const ca=userCache[o];$("#chatTitle").textContent=p||ca?.name||"Chat";const im=$("#chatAvatarImg");if(im){if(ca?.photo_url||ca?.photoURL)im.innerHTML=`<img src="${ca.photo_url||ca.photoURL}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;else im.textContent=(ca?.avatar||ca?.name?.[0]||"?").toUpperCase();}if(currentUser)supabase.from("users").update({current_chat_with:o,is_online:true,last_seen:new Date().toISOString()}).eq("id",currentUser.id).then(()=>{});listenToOtherPresence(o);supabase.from("chats").update({unread_count:{...((ca||{}).unread_count||{}),[currentUser.id]:0}}).eq("id",c).then(()=>{});const load=async()=>{const {data:m}=await supabase.from("messages").select("*").eq("chat_id",c).order("created_at",{ascending:true}).limit(100);const b=$("#chatMessages");b.innerHTML="";if(!m)return;m.forEach(d=>{const r=document.createElement("div");r.className="msg-row "+(d.from_id===currentUser.id?"out":"in");const bu=document.createElement("div");bu.className="bubble "+(d.from_id===currentUser.id?"out":"in");const da=d.created_at?new Date(d.created_at):new Date();const ts=da.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:true});let tc="sent",ti=`<i class="fas fa-check"></i>`;if(d.from_id===currentUser.id){if(d.status==="read"||d.read){tc="read";ti=`<i class="fas fa-check-double"></i>`;}else if(d.status==="delivered"){tc="delivered";ti=`<i class="fas fa-check-double"></i>`;}}const tk=d.from_id===currentUser.id?`<span class="ticks ${tc}">${ti}</span>`:"";const fh=getFileBubbleHtml(d);const mid="msg_"+d.id;bu.innerHTML=fh?`${fh}<span class="msg-time">${ts} ${tk}</span>`:`<span id="${mid}" class="msg-text">${escapeHtml(d.text)}</span><span class="msg-time">${ts} ${tk}</span>`;r.appendChild(bu);b.appendChild(r);if(!fh&&d.from_id!==currentUser.id&&d.text&&!d.text.startsWith("🎤")){const ml=localStorage.getItem("ddchat_lang")||"en",or=d.original_lang||"auto";if(ml!==or){const k=ml+"::"+d.text.trim(),el=document.getElementById(mid);if(transCache[k]){if(el)el.textContent=transCache[k];}else googleTranslate(d.text,or,ml).then(tr=>{transCache[k]=tr;localStorage.setItem("ddchat_trans_v3",JSON.stringify(transCache));if(el)el.textContent=tr;});}}if(d.from_id!==currentUser.id&&currentChatWith===d.from_id&&d.status!=="read")supabase.from("messages").update({status:"read"}).eq("id",d.id).then(()=>{});});renderPendingLocal();requestAnimationFrame(()=>{b.scrollTop=b.scrollHeight;});};load();chatChannel=supabase.channel('chat-'+c).on('postgres_changes',{event:'*',schema:'public',table:'messages',filter:`chat_id=eq.${c}`},()=>load()).subscribe();}
