async function sendMessage(){const t=$("#messageInput").value.trim();if(!t||!currentChatId)return;const b=$("#chatMessages"),id="txt_"+Date.now(),ts=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:true});b.insertAdjacentHTML("beforeend",`<div id="${id}" class="msg-row out"><div class="bubble out"><span class="msg-text">${escapeHtml(t)}</span><span class="msg-time">${ts} <span class="ticks sent"><i class="fas fa-check"></i></span></span></div></div>`);b.scrollTop=b.scrollHeight;$("#messageInput").value="";const ml=localStorage.getItem("ddchat_lang")||"en",ol=userCache[currentChatWith]?.is_online,st=ol?"delivered":"sent";try{await supabase.from("messages").insert({chat_id:currentChatId,from_id:currentUser.id,text:t,original_lang:ml,status:st,created_at:new Date().toISOString()});const {data:cd}=await supabase.from("chats").select("unread_count").eq("id",currentChatId).single();const uc=cd?.unread_count||{};uc[currentChatWith]=(uc[currentChatWith]||0)+1;await supabase.from("chats").update({last_msg:t,updated_at:new Date().toISOString(),unread_count:uc}).eq("id",currentChatId);document.getElementById(id)?.remove();}catch(e){document.getElementById(id)?.remove();alert("Send failed, check network");}}
