async function compressImage(f){return new Promise(r=>{const i=new Image(),rd=new FileReader();rd.onload=e=>{i.src=e.target.result;};i.onload=()=>{let w=i.width,h=i.height,m=600;if(w>m||h>m){if(w>h){h*=m/w;w=m;}else{w*=m/h;h=m;}}const c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(i,0,0,w,h);c.toBlob(b=>r(b),"image/jpeg",0.5);};i.onerror=()=>r(f);rd.readAsDataURL(f);});}
