function getPendingKey(){return `dd_pending_${currentUser?.id}_${currentChatId}`;}function getAllPending(){try{return JSON.parse(localStorage.getItem(getPendingKey())||"[]");}catch{return[];}}function savePending(a){localStorage.setItem(getPendingKey(),JSON.stringify(a));}function addPendingLocal(i){const a=getAllPending();a.push(i);savePending(a);}function updatePendingLocal(i,p){const a=getAllPending();const x=a.findIndex(v=>v.id===i);if(x>=0){a[x]={...a[x],...p};savePending(a);}}function removePendingLocal(i){let a=getAllPending();a=a.filter(x=>x.id!==i);savePending(a);}
